// Actual server-page SSR with synthetic identities/snapshots and unchanged production CSS.
// No authenticated website, backend, scans, decisions or owner preview is touched.
import fs from 'node:fs';import http from 'node:http';import {pathToFileURL} from 'node:url';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';
const stage='F:/VisibleMedicine/staging/20261023-studio-review-queue',site=stage+'/website',root=stage+'/browser',cssRoot='F:/VisibleMedicine/staging/20261023-studio-note-recovery/website/dist/client/_next/static/css',sha=b=>createHash('sha256').update(b).digest('hex');fs.mkdirSync(root,{recursive:true});
const {renderStudioFixture}=await import(pathToFileURL(site+'/tests/studio-review-queue-page-fixture.mjs'));
const cssFiles=fs.readdirSync(cssRoot).filter(n=>/^(index\.|StudioShell\.)/.test(n)&&n.endsWith('.css'));assert.equal(cssFiles.length,2);
const cssMap=new Map(cssFiles.map(n=>['/qa-css/'+n,fs.readFileSync(cssRoot+'/'+n)]));let port,sequence=0;
const server=http.createServer(async(req,res)=>{try{res.setHeader('Cache-Control','no-store');const url=new URL(req.url,'http://127.0.0.1:'+port);
 if(req.method==='POST'&&url.pathname==='/qa-evidence') {if(req.headers.origin!=='http://127.0.0.1:'+port){res.writeHead(403).end();return;}let body='';for await(const chunk of req){body+=chunk;if(Buffer.byteLength(body)>65536)throw Error('Evidence too large');}const value=JSON.parse(body);fs.writeFileSync(root+'/ui-'+(++sequence)+'.json',JSON.stringify({at:new Date().toISOString(),...value},null,2)+'\n',{flag:'wx'});res.end('Saved synthetic evidence');return;}
 if(req.method!=='GET'){res.writeHead(405).end();return;}if(cssMap.has(url.pathname)){res.setHeader('Content-Type','text/css');res.end(cssMap.get(url.pathname));return;}
 const page=url.pathname==='/studio/workspace'?'workspace':url.pathname==='/studio/publishing'?'publishing':null;if(!page){res.writeHead(404).end();return;}
 const params={};for(const [k,v]of url.searchParams){params[k]=k in params?[...(Array.isArray(params[k])?params[k]:[params[k]]),v]:v;}
 const result=await renderStudioFixture(page,params);res.setHeader('Content-Type','text/html');res.end('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Isolated Studio queue QA</title>'+cssFiles.map(n=>'<link rel="stylesheet" href="/qa-css/'+n+'">').join('')+'</head><body><aside style="padding:12px;background:#fff4d6;color:#172f36">Synthetic page fixture — not your signed-in website. Actions are display markers only. <a href="/studio/workspace">Fixture home</a> <button id="save-qa" type="button">Save synthetic QA evidence</button><span id="saved-status"></span></aside>'+result.html+'<script>document.getElementById("save-qa").addEventListener("click",async()=>{const response=await fetch("/qa-evidence",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({url:location.href,width:innerWidth,scrollWidth:document.documentElement.scrollWidth,text:document.body.innerText,queueCards:document.querySelectorAll(".studio-action-queues>div>a").length,actions:[...document.querySelectorAll("[data-release-action]")].map(n=>n.getAttribute("data-release-action"))})});document.getElementById("saved-status").textContent=await response.text();});</script></body></html>');
 }catch(error){res.writeHead(500).end('Synthetic fixture failed');console.error(error);}});
server.listen(0,'127.0.0.1',()=>{port=server.address().port;const sources=['app/studio/workspace/page.tsx','app/studio/publishing/page.tsx','lib/studio-queues.ts','lib/studio-review-queue.ts','tests/studio-review-queue-page-fixture.mjs'].map(p=>({path:p,sha256:sha(fs.readFileSync(site+'/'+p))}));const record={at:new Date().toISOString(),pid:process.pid,url:'http://127.0.0.1:'+port+'/studio/workspace',sources,css:[...cssMap].map(([path,bytes])=>({path,sha256:sha(bytes)})),syntheticOnly:true,previewChanged:false};fs.writeFileSync(root+'/STARTED.json',JSON.stringify(record,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({pid:process.pid,url:record.url}));});
